dict(id='sd10', title='Design Checkpointing for Large-Scale Distributed Training', component='p64-bounded-blocking-queue',
 companies=['Anthropic','NVIDIA','Google','Meta'], source='Main tutorial: distributed training / storage for ML chapters; interview-mastery-courses: Systems & AI Infrastructure "Fault tolerance in training"',
 analogy='Saving a video game during a boss fight with 1,000 players. If everyone stops to write their save file to the same slow disk, the game freezes for minutes. Instead each player quickly copies their save into local memory (snapshot), keeps playing, and a background courier (bounded queue — the component) uploads the files; the queue\'s fixed size stops the courier from eating all the memory.',
 clarify=['Model size and parallelism layout (DP/TP/PP)?','Failure rate (MTBF per GPU) and acceptable lost work?','Storage: parallel FS, object store, local NVMe?','Must checkpoints be resharded for a different GPU count?','Retention (how many to keep)?'],
 reqs=dict(functional=['Periodic consistent checkpoints of weights, optimizer, data-loader position, RNG','Restart from latest valid checkpoint','Reshard on restore'],nonfunctional=['Training stall < 5% of time','Lose < 30 min of work per failure','Checkpoint integrity (no torn checkpoints)']),
 capacity=['70B params: weights FP16 140 GB + Adam (FP32 master + 2 moments) ≈ 70B × 12 B = 840 GB → ~1 TB per checkpoint.','1 TB at 10 GB/s aggregate → 100 s if synchronous; with 1,024 GPUs each writes ~1 GB in parallel → seconds to local memory, minutes to object store in the background.','Optimal interval (Young/Daly): sqrt(2 × checkpointCost × MTBF); with cost 60 s and cluster MTBF 4 h → ~22 min.'],
 nodes=[('train','Trainer ranks (GPU)',90,280),('snap','Host-memory snapshot',300,140),('q','Bounded upload queue (backpressure)',500,280),('nvme','Local NVMe tier',300,440),('obj','Object store (durable)',740,280),('meta','Checkpoint manifest + commit',740,460),('ctl','Job controller (restart)',740,110)],
 edges=[('train','snap'),('snap','q'),('q','obj'),('snap','nvme'),('obj','meta'),('ctl','train'),('meta','ctl')],
 flows=[dict(name='Async checkpoint',path=['train','snap','q','obj','meta']),dict(name='Restart after failure',path=['ctl','meta','obj','train'])],
 fail={'train':'Rank dies → whole job restarts (collectives need all ranks) from the last COMMITTED manifest.','q':'Upload falls behind → queue fills → backpressure: skip/merge the next checkpoint instead of blocking training or OOMing the host.','obj':'Object store slow/down → keep the latest checkpoint on local NVMe + peer replicas; retry later.','meta':'Manifest write fails → checkpoint is not committed, so restart uses the previous one (no torn checkpoint).'},
 deep=['Two-phase: snapshot to host memory (fast, blocks training briefly) → async persist; commit by atomically writing a manifest last.','Sharded checkpoints: each rank writes its own shard; manifest maps tensors to shards for resharding.','In-memory redundancy: replicate snapshots to peer nodes for fast recovery without the object store.','Integrity: checksums per shard; verify before commit.'],
 tradeoffs=['Frequency vs overhead (Young/Daly).','Async (needs host memory, more complexity) vs sync (simple, stalls).','Full vs incremental/delta checkpoints.'],
 failures=['Torn checkpoint from a crash mid-write → manifest-last commit.','Silent data corruption → checksums + periodic restore tests.','Storage hotspot when 1,000 ranks write at once → stagger and spread prefixes.'],
 rubric=['Size math','Async pipeline with backpressure','Atomic commit','Interval reasoning','Restart/reshard path']),
dict(id='sd11', title='Design a Build / CI Artifact Cache (remote build cache)', component='p20-lru-cache',
 companies=['Google','Microsoft','Meta','NVIDIA'], source='Main tutorial: developer infrastructure / build systems; interview-mastery-courses: Google "Caching" and storage design prompts',
 analogy='A shared freezer for pre-cooked meals. Every recipe + exact ingredient list gets a unique label (content hash). If anyone already cooked that exact meal, you take it from the freezer instead of cooking. When the freezer is full you throw out the meal nobody touched for the longest time (LRU — the component).',
 clarify=['Number of engineers / CI jobs per day?','Artifact sizes (KB object files vs GB containers)?','Hit-rate target?','Trust model: can developer laptops write to the cache?','Multi-region offices?'],
 reqs=dict(functional=['get(actionKey) → outputs','put(actionKey, outputs) from trusted builders','Content-addressed blob storage (CAS)','Eviction and quotas'],nonfunctional=['p99 get < 50 ms for small blobs','50k builds/day, 80%+ hit rate','Never serve a wrong artifact (integrity)']),
 capacity=['50k builds × 20k actions × 30% miss → 300M puts/day ≈ 3.5k puts/s; gets ≈ 10× → 35k/s.','Avg blob 200 KB → 60 TB written/day, mostly duplicates; CAS dedupes. Keep ~200 TB hot with LRU eviction.','Per-region cache in front of a global store; small blobs in memory/SSD tier.'],
 nodes=[('dev','Developers / CI runners',80,280),('front','Cache frontend (auth, routing)',280,280),('ac','Action cache (key → digests)',490,140),('mem','Hot tier (RAM/SSD LRU)',490,420),('cas','CAS blob store (object storage)',730,280),('exec','Remote executors',730,470),('gc','Eviction / GC',730,100)],
 edges=[('dev','front'),('front','ac'),('front','mem'),('mem','cas'),('ac','cas'),('exec','front'),('gc','cas')],
 flows=[dict(name='Cache hit',path=['dev','front','ac','front','mem','dev']),dict(name='Miss → build → put',path=['dev','front','exec','front','cas','ac'])],
 fail={'front':'Frontend down → clients fall back to local builds (slower, still correct).','mem':'Hot tier lost → reads fall through to CAS; hit latency rises, not correctness.','cas':'Blob store down → treat as cache miss everywhere; builds slow down.','ac':'Action-cache corruption → digests verified on read; mismatches are dropped as misses.'},
 deep=['Keys: hash of command line + input file digests + toolchain + env → hermeticity is essential.','Two-level: action cache (small entries) and CAS (blobs by SHA-256); clients verify digests.','Eviction: LRU on the hot tier (component); size-aware / TTL for the global tier; never evict blobs referenced by fresh action entries first.','Security: only CI (trusted) writes; laptops read-only, or per-user namespaces.'],
 tradeoffs=['Hit rate vs storage cost.','Strict hermeticity (correct, harder) vs leaky builds (wrong cache hits).','Global vs per-region caches (latency vs duplication).'],
 failures=['Cache poisoning → write ACLs, signed provenance.','Non-deterministic outputs → low hit rate; detect via digest churn.','Thundering herd on a new toolchain → coalesce identical in-flight requests.'],
 rubric=['Content addressing','Correctness/hermeticity','Eviction policy','Security model','Capacity']),

