 nodes=[('cli','Clients (HTTP)',80,280),('fe','Front-end (auth, routing)',270,280),('meta','Metadata service (sharded KV, Raft)',480,130),('place','Placement (hash ring + failure domains)',480,430),('d1','Storage nodes AZ1',760,130),('d2','Storage nodes AZ2',760,280),('d3','Storage nodes AZ3',760,430),('repair','Repair / scrubber',920,280)],
