 edges=[('prod','b1'),('b1','b2'),('b1','b3'),('ctrl','b1'),('b1','cons'),('b1','tier')],
 flows=[dict(name='Produce (acks=all)',path=['prod','b1','b2','b1','b3','b1','prod']),dict(name='Consume',path=['cons','b1','cons'])],
